import {profile,projects,skills,certificates,leadership} from './data.js';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
projects[1].media=[1,2,3,4].map(n=>({src:`assets/sipori${n}.png`,alt:`Sipori application screenshot ${n} from the project repository`}));projects[3].media=[{src:'assets/truth.png',alt:'Truth in Tales website preview from the project repository'}];
let filter='All Projects',index=0,gallery=0;const filtered=()=>projects.filter(p=>filter==='All Projects'||p.category.includes(filter));
function tabs(target,items,active,callback){$(target).innerHTML=items.map(v=>`<button aria-pressed="${v===active}">${esc(v)}</button>`).join('');$(target).querySelectorAll('button').forEach((b,i)=>b.onclick=()=>callback(items[i]));}
function media(p){const m=p.media[gallery%Math.max(1,p.media.length)];return `<div class="media-board">${m?`<img src="${esc(m.src)}" alt="${esc(m.alt)}" loading="lazy">`:`<div class="project-art"><span class="art-symbol" aria-hidden="true">${p.symbol}</span><strong>${p.name}</strong><small>PROJECT ARTWORK · SCREENSHOTS TO BE ADDED</small></div>`}<div class="media-caption"><span>${m?'ACTUAL PROJECT SCREENSHOT':'ARCHIVE / VISUAL PLACEHOLDER'}</span>${p.media.length>1?`<span class="gallery-buttons"><button data-gallery="-1" aria-label="Previous screenshot">←</button> ${gallery+1} / ${p.media.length}<button data-gallery="1" aria-label="Next screenshot">→</button></span>`:''}</div></div>`}
function actions(p){return `${p.repo?`<a href="https://github.com/${p.repo}" target="_blank" rel="noreferrer">Repository ↗</a>`:''}${p.live?`<a href="${p.live}" target="_blank" rel="noreferrer">${p.liveLabel||'Visit website ↗'}</a>`:''}`}
function bindGallery(p,container,render){container.querySelectorAll('[data-gallery]').forEach(b=>b.onclick=()=>{gallery=(gallery+Number(b.dataset.gallery)+p.media.length)%p.media.length;render()});}
function renderProject(){const list=filtered();index=(index+list.length)%list.length;const p=list[index];tabs('#project-filters',['All Projects','UI/UX','Web Development','Mobile Development','AI / Machine Learning'],filter,v=>{filter=v;index=0;gallery=0;renderProject()});$('#showcase').innerHTML=`<article class="project-spread"><div class="project-copy"><span class="project-number">FILE ${String(projects.indexOf(p)+1).padStart(2,'0')} / ${esc(p.type.toUpperCase())}</span><h3>${esc(p.name)}</h3><p class="subtitle">${esc(p.subtitle)}</p><p>${esc(p.description)}</p><div class="chips">${p.tech.map(t=>`<span>${esc(t)}</span>`).join('')}</div><div class="project-actions"><button class="button red" id="case-study">Open case study ↗</button>${actions(p)}</div></div><div>${media(p)}<p class="media-note">${esc(p.note)}</p></div></article>`;$('#project-index').textContent=`${String(index+1).padStart(2,'0')} / ${String(list.length).padStart(2,'0')}`;$('#project-shelf').innerHTML=list.map((x,i)=>`<button aria-current="${i===index}"><small>FILE ${String(projects.indexOf(x)+1).padStart(2,'0')}</small>${esc(x.name)}</button>`).join('');$('#project-shelf').querySelectorAll('button').forEach((b,i)=>b.onclick=()=>{index=i;gallery=0;renderProject()});$('#case-study').onclick=()=>openCase(p);bindGallery(p,$('#showcase'),renderProject);}
$('#prev').onclick=()=>{index--;gallery=0;renderProject()};$('#next').onclick=()=>{index++;gallery=0;renderProject()};
const dialog=$('#dialog');function openDialog(html){$('#dialog-content').innerHTML=html;dialog.showModal()}$('#close-dialog').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
function openCase(p){gallery=0;function content(){ $('#dialog-content').innerHTML=`<div class="section-label">PROJECT NOTES / ${esc(p.type)}</div><h2>${esc(p.name)}</h2><p class="subtitle">${esc(p.subtitle)}</p><h3>Overview & purpose</h3><p>${esc(p.description)}</p>${media(p)}<h3>My role & contributions</h3><ul>${p.role.map(r=>`<li>${esc(r)}</li>`).join('')}</ul><h3>Key features</h3><ul>${p.features.map(r=>`<li>${esc(r)}</li>`).join('')}</ul>${p.tech.length?`<h3>Technologies</h3><div class="chips">${p.tech.map(t=>`<span>${esc(t)}</span>`).join('')}</div>`:''}<p class="meta">Contributions are recorded from the supplied portfolio brief. Additional process documentation and authentic media can be added as they become available.</p>${p.name==='Sipori'?'<p>The deployed journal requires private owner authentication. No private records or sign-in credentials are provided.</p>':''}<div class="project-actions">${actions(p)}</div>`;bindGallery(p,$('#dialog-content'),content)}content();dialog.showModal()}
document.querySelectorAll('.cv').forEach(b=>b.onclick=()=>{if(profile.cv){if(b.textContent.includes('Download')){const a=document.createElement('a');a.href=profile.cv;a.download='Nina-Pascua-CV.pdf';a.click()}else window.open(profile.cv,'_blank','noopener')}else openDialog('<span class="section-label">DOCUMENT ARCHIVE</span><h2>CV, coming soon.</h2><p>The original CV PDF has not been supplied yet. Please get in touch for a copy.</p><a class="button red" href="mailto:ninapascua88@gmail.com?subject=CV%20request">Request my CV ↗</a>')});
if(profile.photo){$('.portrait-inner').innerHTML=`<img src="${esc(profile.photo)}" alt="Niña Pascua" style="width:100%;height:100%;object-fit:cover">`}
$('#menu').onclick=()=>{const open=$('#nav').classList.toggle('open');$('#menu').setAttribute('aria-expanded',open)};$('#nav').querySelectorAll('a').forEach(a=>a.onclick=()=>{$('#nav').classList.remove('open');$('#menu').setAttribute('aria-expanded','false')});$('#year').textContent=new Date().getFullYear();
$('#skill-list').innerHTML=Object.entries(skills).map(([name,items])=>`<div><h3>${name.toUpperCase()}</h3><div class="chips">${items.map(x=>`<span>${x}</span>`).join('')}</div></div>`).join('');$('#leadership').innerHTML=leadership.map(([date,org,role])=>`<div class="timeline-item"><span>${date}</span><div><strong>${org}</strong><p>${role}</p></div></div>`).join('');
function renderCerts(active='All'){tabs('#cert-filters',['All',...new Set(certificates.map(c=>c[0]))],active,renderCerts);$('#certificates').innerHTML=certificates.filter(c=>active==='All'||c[0]===active).map(c=>`<article class="certificate"><span>✧</span><div><h3>${esc(c[1])}</h3><p>${esc(c[2])} / ${esc(c[3])}</p></div><small>DOCUMENT TO BE ADDED</small></article>`).join('')}
let repos=[];function safeUrl(url){try{const u=new URL(url);return ['https:','http:'].includes(u.protocol)?esc(u.href):'#'}catch{return '#'}}
function renderRepos(){const q=$('#repo-search').value.toLowerCase(),language=$('#language').value,sort=$('#sort').value;const items=repos.filter(r=>r.name.toLowerCase().includes(q)&&(!language||r.language===language)).sort((a,b)=>sort==='name'?a.name.localeCompare(b.name):sort==='stars'?b.stargazers_count-a.stargazers_count:new Date(b.updated_at)-new Date(a.updated_at));$('#repos').innerHTML=items.length?items.map((r,i)=>`<article class="repo-card"><span class="meta">${String(i+1).padStart(2,'0')} / ${esc(r.language||'Unspecified language')}</span><h3>${esc(r.name)}</h3><p>${esc(r.description||'No description provided.')}</p><div class="chips">${(r.topics||[]).slice(0,5).map(t=>`<span>${esc(t)}</span>`).join('')}</div><div class="meta">★ ${r.stargazers_count} · FORKS ${r.forks_count}<br>UPDATED ${new Date(r.updated_at).toLocaleDateString('en-US',{year:'numeric',month:'short',day:'numeric'})}</div><a href="${safeUrl(r.html_url)}" target="_blank" rel="noreferrer">View repository ↗</a>${r.homepage?`<a href="${safeUrl(r.homepage)}" target="_blank" rel="noreferrer">Website ↗</a>`:''}</article>`).join(''):'<p>No repositories match this selection.</p>'}
function setRepos(data){repos=data;const languages=[...new Set(data.map(r=>r.language).filter(Boolean))].sort();$('#language').innerHTML='<option value="">All languages</option>'+languages.map(l=>`<option>${esc(l)}</option>`).join('');renderRepos()}
async function loadRepos(force=false){$('#refresh').disabled=true;let cache;try{cache=JSON.parse(localStorage.getItem('nina-repos')||'null')}catch{}if(cache?.data){setRepos(cache.data);if(!force&&Date.now()-cache.time<1800000){$('#repo-status').textContent='Public repository snapshot · cached for up to 30 minutes';$('#refresh').disabled=false;return}}$('#repo-status').textContent='Fetching public repositories from GitHub…';try{const response=await fetch('https://api.github.com/users/ninapascua/repos?sort=updated&per_page=100',{signal:AbortSignal.timeout(15000)});if(!response.ok)throw Error('GitHub unavailable');const data=await response.json();if(!Array.isArray(data))throw Error('Invalid repository response');setRepos(data);try{localStorage.setItem('nina-repos',JSON.stringify({time:Date.now(),data}))}catch{}$('#repo-status').textContent=`${data.length} public repositories · updated from GitHub just now`}catch{$('#repo-status').textContent=cache?.data?'GitHub is unavailable. Showing the last cached snapshot.':'GitHub is temporarily unavailable. The selected work and collaborative archive are still available.';if(!cache?.data)$('#repos').innerHTML='<a class="button" href="https://github.com/ninapascua" target="_blank" rel="noreferrer">Browse repositories on GitHub ↗</a>'}finally{$('#refresh').disabled=false}}
$('#collaborative').innerHTML=projects.filter(p=>p.repo&&!p.repo.startsWith('ninapascua/')).map(p=>`<article class="repo-card"><span class="meta">TEAM PROJECT / ${esc(p.repo.split('/')[0])}</span><h3>${p.name}</h3><p>${p.subtitle}</p><a href="https://github.com/${p.repo}" target="_blank" rel="noreferrer">View team repository ↗</a></article>`).join('');['#repo-search','#language','#sort'].forEach(s=>$(s).addEventListener(s==='#repo-search'?'input':'change',renderRepos));$('#refresh').onclick=()=>loadRepos(true);renderProject();renderCerts();loadRepos();
